 120	export function validateReviewResult(value: unknown): string[] {
 121		if (!isPlainObject(value)) return ["ReviewResult must be an object"];
 122		const errors: string[] = [];
 123		if (!isNonEmptyString(value.taskId)) errors.push("taskId must be a non-empty string");
 124		if (!isNonEmptyString(value.verdict) || !REVIEW_VERDICTS.includes(value.verdict as ReviewVerdict)) {
 125			errors.push(`verdict must be one of ${REVIEW_VERDICTS.join(", ")}`);
 126		}
 127		if (typeof value.summary !== "string") errors.push("summary must be a string");
 128		if (typeof value.evidenceFresh !== "boolean") errors.push("evidenceFresh must be a boolean");
 129		if (value.acknowledgeDrift !== undefined) {
 130			if (!isPlainObject(value.acknowledgeDrift)) {
 131				errors.push("acknowledgeDrift must be an object when present");
 132			} else {
 133				const acknowledgement = value.acknowledgeDrift as Record<string, unknown>;
 134				if (acknowledgement.successorTaskId !== undefined && !isNonEmptyString(acknowledgement.successorTaskId)) {
 135					errors.push("acknowledgeDrift.successorTaskId must be a non-empty string when present");
 136				}
 137				if (acknowledgement.commit !== undefined && typeof acknowledgement.commit !== "boolean") {
 138					errors.push("acknowledgeDrift.commit must be a boolean when present");
 139				}
 140				if (acknowledgement.successorTaskId === undefined && acknowledgement.commit !== true) {
 141					errors.push("acknowledgeDrift must name successorTaskId or set commit=true");
 142				}
 143			}
 144		}
 145		if (!Array.isArray(value.findings)) errors.push("findings must be an array");
 146		else {
 147			value.findings.forEach((finding, index) => {
 148				if (!isPlainObject(finding)) {
 149					errors.push(`findings[${index}] must be an object`);
 150					return;
 151				}
 152				if (
 153					!isNonEmptyString(finding.severity) ||
 154					!FINDING_SEVERITIES.includes(finding.severity as FindingSeverity)
 155				) {
 156					errors.push(`findings[${index}].severity must be one of ${FINDING_SEVERITIES.join(", ")}`);
 157				}
 158				if (
 159					!isNonEmptyString(finding.category) ||
 160					!FINDING_CATEGORIES.includes(finding.category as FindingCategory)
 161				) {
 162					errors.push(`findings[${index}].category must be one of ${FINDING_CATEGORIES.join(", ")}`);
 163				}
 164				if (!isNonEmptyString(finding.description)) {
 165					errors.push(`findings[${index}].description must be a non-empty string`);
 166				}
 167			});
 168		}
